import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import path from 'node:path';import {chromium} from 'playwright';import {verificationScreenshot} from '../../engine/verify-screenshot.mjs';
const root=path.resolve('work/uae'),records=JSON.parse(await readFile(path.join(root,'ultimate-menu-variant-records.json'))),browser=await chromium.launch({channel:'chrome'}),results=[];
try{for(const record of records)for(const width of [1440,390]){
 const page=await browser.newPage({viewport:{width,height:900},reducedMotion:'reduce'});page.setDefaultTimeout(8000);await page.goto(record.url,{waitUntil:'networkidle'});const widget=page.locator('.elementor-widget-navigation-menu'),flyout=record.settings.layout==='flyout';await verificationScreenshot(page,path.join(root,'variant-'+record.variant+'-'+width+'-closed.png'));
 const toggle=widget.locator('.hfe-nav-menu__toggle');if(await toggle.isVisible()){if(flyout)await toggle.locator('.hfe-nav-menu-icon').click();else await toggle.click();}
 if(flyout)await widget.locator('.hfe-flyout-show').waitFor();
 const parents=widget.locator('.hfe-has-submenu-container');assert.equal(await parents.count(),2);
 for(let i=0;i<2;i++){const button=parents.nth(i);if(!flyout&&width===1440)await button.hover();else await button.click();await page.waitForFunction(index=>{const button=document.querySelectorAll('.elementor-widget-navigation-menu .hfe-has-submenu-container')[index],p=button.nextElementSibling;return getComputedStyle(p).visibility==='visible'&&Number(getComputedStyle(p).opacity)>0;},i);}
 await page.waitForTimeout(350);await verificationScreenshot(page,path.join(root,'variant-'+record.variant+'-'+width+'-open.png'));await writeFile(path.join(root,'variant-'+record.variant+'-'+width+'.html'),await widget.evaluate(el=>el.outerHTML));
 const geometry=await widget.locator('nav').evaluate(el=>{const r=el.getBoundingClientRect();return {x:r.x,width:r.width,height:r.height}});results.push({variant:record.variant,width,depth:3,opened:true,geometry});if(flyout){await widget.locator('.hfe-flyout-close').click();await page.waitForFunction(()=>!document.querySelector('.hfe-flyout-show'));}await page.close();
}await writeFile(path.join(root,'ultimate-variants-source-check.json'),JSON.stringify(results,null,2));console.log(JSON.stringify(results));}finally{await browser.close();}
